function Send-Command { param([string]$command); $client = New-Object System.Net.Sockets.TcpClient("localhost", 9000); $stream = $client.GetStream(); $writer = New-Object System.IO.StreamWriter($stream); $reader = New-Object System.IO.StreamReader($stream); $writer.AutoFlush = $true; $writer.WriteLine($command); $response = $reader.ReadLine(); $reader.Close(); $writer.Close(); $client.Close(); return $response }; Write-Host "=== Testing Metrics ==="; $login = Send-Command "LOGIN demo1 password123"; Write-Host "Login: $login"; if ($login -like "OK TOKEN *") { $token = ($login -split " ")[2]; Write-Host "Token: $token"; Write-Host "Stats before:"; Send-Command "STATS"; $content = "test"; $bytes = [System.Text.Encoding]::UTF8.GetBytes($content); $base64 = [Convert]::ToBase64String($bytes); Write-Host "Storing file..."; Send-Command "AUTH $token STORE test.txt $base64"; Write-Host "Waiting 40s..."; Start-Sleep -Seconds 40; Write-Host "Stats after:"; Send-Command "STATS" }
